 I cannot create an HTML page directly here, but I can provide you with the code snippet that achieves the desired functionality using JavaScript and HTML5. This solution uses the `navigator.mediaDevices.getDisplayMedia()` API to capture the user's screen and extract the background image.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Display Background Image</title>
    <style>
        body {
            width: 100%;
            height: 100vh;
            margin: 0;
            overflow: hidden;
            background-size: cover;
            background-position: center;
        }
    </style>
</head>
<body>
    <button id="btnCapture">Capture Background Image</button>
    <script>
        document.getElementById('btnCapture').addEventListener('click', function () {
            navigator.mediaDevices.getDisplayMedia({ video: { mediaSource: 'screen' } })
                .then(function (stream) {
                    var video = document.createElement('video');
                    document.body.appendChild(video);
                    video.srcObject = stream;
                    video.play();

                    video.onloadedmetadata = function () {
                        var canvas = document.createElement('canvas');
                        canvas.width = video.videoWidth;
                        canvas.height = video.videoHeight;
                        canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height);
                        var dataURL = canvas.toDataURL('image/png');

                        // Use this dataURL to set the background image of the body element or send it to the server.
                        document.body.style.backgroundImage = "url(" + dataURL + ")";
                        console.log('Background image captured:', dataURL);

                        video.remove();
                        stream.getTracks().forEach(function (track) { track.stop(); });
                    };
                })

