 Here's an example implementation of the `RedisClient` class in Node.js using the `redis` npm package:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();

    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  async isAlive() {
    return new Promise((resolve, reject) => {
      this.client.ping((err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply === 'PONG');
        }
      });
    });
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          reject(err);
        } else {
          resolve(value);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This `RedisClient` class initializes a new Redis client when constructed and sets up an error event listener to log any errors to the console. It also defines the required methods: `isAlive`, `get`, `set`, and `del`. Each method uses Promises to handle asynchronous Redis operations and either resolves with the result

